import { readFileSync } from "fs"
import { join, dirname } from "path"
import { fileURLToPath } from "url"

const __dirname = dirname(fileURLToPath(import.meta.url))
const promptDir = join(__dirname, "prompts")

function readPrompt(name: string): string {
  const fullPath = join(promptDir, name)
  try {
    return readFileSync(fullPath, "utf-8")
  } catch (e) {
    throw new Error(
      `Failed to read agent prompt file: ${fullPath}\n` +
      `Ensure the @opensploit/core package includes the prompts directory.\n` +
      `Original error: ${e instanceof Error ? e.message : String(e)}`
    )
  }
}

/**
 * Bash commands denied for pentest agents — forces them to invoke security
 * tools through `cli_in_container` / `mcp_tool` so the calls run in isolated
 * containers with logging.
 */
const bashSecurityDenials: Record<string, "allow" | "ask" | "deny"> = {
  "*": "allow",
  "nmap*": "deny",
  "ssh *": "deny",
  "scp *": "deny",
  "sqlmap*": "deny",
  "hydra*": "deny",
  "nikto*": "deny",
  "gobuster*": "deny",
  "ffuf*": "deny",
  "curl *": "deny",
  "wget *": "deny",
  "nc *": "deny",
  "netcat*": "deny",
  "metasploit*": "deny",
  "msfconsole*": "deny",
  "john*": "deny",
  "hashcat*": "deny",
}

/**
 * External directory permissions — session dir allowed, others ask.
 *
 * Two forms covered (belt-and-suspenders):
 *   - /session/* and /session/**            — virtual path the agent emits
 *   - /tmp/opensploit-session-*[/...]       — translated host path after
 *                                             tool.execute.before rewrites it
 * Whichever form the permission system sees at check-time, one of these
 * patterns matches and grants allow without prompting the user.
 */
const pentestExternalDir: Record<string, "allow" | "ask" | "deny"> = {
  "*": "ask",
  "/session/*": "allow",
  "/session/**": "allow",
  "/tmp/opensploit-session-*": "allow",
  "/tmp/opensploit-session-*/**": "allow",
}

/**
 * Shared permission ruleset for pentest sub-agents. Order matters: the
 * permission system uses `findLast` for resolution, so specific patterns
 * must follow general ones to win.
 *
 *   - `todowrite: "allow"` — sub-agents get their own scratchpad todo list.
 *   - `task: { "*": "deny", "pentest/*": "allow" }` — restricts task
 *     spawning to pentest/* agents only.
 *
 * The master agent overrides `task` to a blanket allow (see `pentest`
 * config below) because the master may spawn any agent type, not just
 * pentest/*. Recursive depth and the tool-runner exemption are enforced
 * fork-side in tool/task.ts via session-level permission rules.
 */
const pentestPermission = {
  "*": "allow" as const,
  doom_loop: "ask" as const,
  external_directory: pentestExternalDir,
  bash: bashSecurityDenials,
  todowrite: "allow" as const,
  task: { "*": "deny" as const, "pentest/*": "allow" as const },
}

/**
 * Agent config type matching what the config hook expects.
 * These fields map to the Agent schema in opencode config.ts.
 */
type AgentConfig = {
  mode: "primary" | "subagent" | "all"
  description: string
  prompt: string
  color?: string
  temperature?: number
  hidden?: boolean
  // Cap on internal LLM turns within a single sub-agent invocation.
  // opencode honors this at session/prompt.ts (`agent.steps ?? Infinity`).
  // Used by leaf executors to bound runaway loops (strategy drift,
  // hallucinated repetition).
  steps?: number
  permission?: Record<string, any>
}

/**
 * Load all pentest agent definitions for registration via the config hook.
 *
 * Returns a record keyed by agent name. The config hook merges these
 * into config.agent, making them available to the agent system.
 */
export function loadAgents(): Record<string, AgentConfig> {
  const base = readPrompt("pentest-base.txt")
  // Slim base for leaf executors (tool-runner). Drops ~80% of pentest-base —
  // the parts about orchestration, tool-runner delegation mandate, web research,
  // todo tracking, sub-agent spawning, captcha. Keeps the universal mechanics
  // (workspace paths, non-interactive execution, subagent contract). Cuts
  // per-spawn input cost ~5× on the system prompt and reduces irrelevant-rule
  // distraction that contributes to strategy drift in long internal turns.
  const leafBase = readPrompt("pentest-base-leaf.txt")

  return {
    pentest: {
      mode: "primary",
      color: "#e74c3c",
      description:
        "Master penetration testing agent that orchestrates security assessments",
      prompt: base + "\n\n" + readPrompt("pentest.txt"),
      temperature: 0.3,
      permission: {
        ...pentestPermission,
        question: "allow",
        plan_enter: "allow",
        // Master may spawn any agent type, not just pentest/*. Override the
        // sub-agent restriction on `task` to a blanket allow.
        task: "allow" as const,
      },
    },

    "pentest/recon": {
      mode: "subagent",
      color: "#3498db",
      description:
        "Reconnaissance phase - discover services and gather information",
      prompt: base + "\n\n" + readPrompt("pentest/recon.txt"),
      hidden: true,
      permission: pentestPermission,
    },

    "pentest/enum": {
      mode: "subagent",
      color: "#9b59b6",
      description:
        "Enumeration phase - detailed service analysis and vulnerability identification",
      prompt: base + "\n\n" + readPrompt("pentest/enum.txt"),
      hidden: true,
      permission: pentestPermission,
    },

    "pentest/exploit": {
      mode: "subagent",
      color: "#e74c3c",
      description:
        "Exploitation phase - attempt to gain access using discovered vulnerabilities",
      prompt: base + "\n\n" + readPrompt("pentest/exploit.txt"),
      hidden: true,
      permission: pentestPermission,
    },

    "pentest/post": {
      mode: "subagent",
      color: "#f39c12",
      description:
        "Post-exploitation phase - privilege escalation, lateral movement, persistence",
      prompt: base + "\n\n" + readPrompt("pentest/post.txt"),
      hidden: true,
      permission: pentestPermission,
    },

    "pentest/report": {
      mode: "subagent",
      color: "#27ae60",
      description:
        "Reporting phase - aggregate findings and generate comprehensive reports",
      prompt: base + "\n\n" + readPrompt("pentest/report.txt"),
      hidden: true,
      // Report agent: no bash, no spawning. Only reads findings and writes
      // reports. todowrite enabled so it can track its report sections.
      permission: {
        "*": "allow",
        doom_loop: "ask",
        external_directory: pentestExternalDir,
        bash: { "*": "deny" },
        todowrite: "allow",
        task: { "*": "deny" },
      },
    },

    "pentest/validator": {
      mode: "subagent",
      color: "#8e44ad",
      description:
        "Validation re-run — reproduces a solved engagement to confirm the steps and capture a clean solve-doc",
      // Reuses the FULL master orchestration (base + pentest.txt) so it can
      // drive the whole procedure, then a validation preamble (validator.txt)
      // reframes the goal to reproduce-and-capture and forbids nesting.
      prompt:
        base + "\n\n" + readPrompt("pentest.txt") + "\n\n" + readPrompt("pentest/validator.txt"),
      temperature: 0.2,
      hidden: true,
      // Can spawn phase agents to re-run the procedure, but NEVER another
      // validator (belt-and-suspenders alongside the prompt guard).
      permission: {
        ...pentestPermission,
        task: { "*": "deny" as const, "pentest/*": "allow" as const, "pentest/validator": "deny" as const },
      },
    },

    "pentest/research": {
      mode: "subagent",
      color: "#1abc9c",
      description:
        "OSINT and research specialist - CVE details, exploit research, default credentials",
      prompt: base + "\n\n" + readPrompt("pentest/research.txt"),
      hidden: true,
      permission: pentestPermission,
    },

    "pentest/build": {
      mode: "subagent",
      color: "#e67e22",
      description:
        "Exploit and payload builder - finds or creates tested exploits",
      prompt: base + "\n\n" + readPrompt("pentest/build.txt"),
      hidden: true,
      permission: pentestPermission,
    },

    "pentest/captcha": {
      mode: "subagent",
      color: "#f1c40f",
      description:
        "CAPTCHA coordinator - detects CAPTCHAs and hands off to human user for solving",
      prompt: base + "\n\n" + readPrompt("pentest/captcha.txt"),
      temperature: 0.2,
      hidden: true,
      // Captcha is a leaf executor — it does VNC handover, not delegation.
      // Explicit task deny is defense-in-depth alongside the session-level
      // restriction set in tool/task.ts.
      permission: {
        ...pentestPermission,
        question: "allow",
        task: { "*": "deny" as const },
      },
    },

    "pentest/tool-runner": {
      mode: "subagent",
      color: "#16a085",
      description:
        "Tool executor - runs one tool call via cli_in_container or mcp_tool and returns a clean <tool_result> summary. Invoked by phase agents; does not decide strategy or pivot.",
      // Use the slim leaf base, not the full pentest-base. Tool-runner's job
      // is mechanical (lookup-execute-classify-emit), not orchestrative — most
      // of pentest-base (tool-execution mandate, todo tracking, delegation,
      // captcha rules, web research) doesn't apply to it and only inflates
      // the system prompt that gets re-sent on every internal turn. See the
      // "leaf executor" carve-out paragraph in pentest-base.txt § Tool Execution.
      prompt: leafBase + "\n\n" + readPrompt("pentest/tool-runner.txt"),
      temperature: 0.1,
      hidden: true,
      // Cap internal turns. Empirical p95 from a Forest engagement (24
      // spawns) was 13; the three highest (12, 13, 17) were either
      // strategy drift or hallucination loops. Set high enough that
      // legitimate complex recoveries (multi-step impacket chains, gcc
      // compile + script execution + result parsing) have ample room,
      // while still bounding pathological loops. The leaf-base "no
      // reformulation" rule is the primary defense — this cap is the
      // belt-and-suspenders ceiling.
      steps: 20,
      // Tool-runner is a leaf executor by design — its prompt explicitly
      // forbids spawning. Explicit task deny is defense-in-depth alongside
      // the session-level restriction set in tool/task.ts.
      permission: {
        ...pentestPermission,
        task: { "*": "deny" as const },
      },
    },
  }
}
